package dev.smokekitchen.cooking;

import dev.smokekitchen.content.ContentCatalog;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class FinishingCookingTest {
    private DishRecipe recipe(String id){if(ContentCatalog.DISHES.isEmpty())ContentCatalog.load();return ContentCatalog.DISHES.stream().filter(r->r.id().equals(id)).findFirst().orElseThrow();}
    private CookingBatch batch(CookingBatch.Method method){var b=new CookingBatch();b.method=method;b.oil=1;b.salt=1;b.soy=1;return b;}
    private void ready(CookingBatch b){b.ingredients.forEach(p->p.cooked=1);}
    private void stir(CookingBatch b){for(int i=0;i<3;i++)b.stir();}
    private void turnAfterSetting(CookingBatch b){b.ingredients.forEach(p->p.cooked=.45);b.turn();ready(b);}
    @Test void coldTurnSpamCannotReplaceSettingAndCookingTheOtherSide(){var b=batch(CookingBatch.Method.FRY);b.add("fish",CookingBatch.Cut.WHOLE,1,false,false);for(int i=0;i<8;i++)b.turn();assertFalse(b.ingredients.getFirst().turnedAfterSetting);b.ingredients.getFirst().cooked=.4;b.turn();assertTrue(b.ingredients.getFirst().turnedAfterSetting);assertEquals(.4,b.ingredients.getFirst().cookedAtTurn);}
    @Test void coldMixingRequiresRawFoodAndRestartsAfterAnotherAddition(){var b=batch(CookingBatch.Method.FRY);b.add("egg",CookingBatch.Cut.WHOLE,1,false,false);b.stir();b.stir();assertEquals(2,b.coldMixes);b.add("scallion",CookingBatch.Cut.DICE,1,false,false);assertEquals(0,b.coldMixes);ready(b);b.stir();assertEquals(0,b.coldMixes);}
    @Test void garlicGreensNeedMincedGarlicBrieflyFriedBeforeGreens(){var r=recipe("garlic_greens");var b=batch(CookingBatch.Method.STIR_FRY);b.temperature=130;b.add("garlic",CookingBatch.Cut.MINCE,1,false,false);b.ingredients.getFirst().cooked=.2;for(int i=0;i<2;i++)b.add("cabbage",CookingBatch.Cut.SHRED,1,false,false);ready(b);stir(b);assertTrue(r.matches(b));b.ingredients.get(1).priorCooked.put("garlic",0d);assertEquals("stage",r.problem(b).orElseThrow().key());}
    @Test void omeletteNeedsColdMixingAndAnActualSetThenTurn(){var r=recipe("scallion_omelette");var b=batch(CookingBatch.Method.FRY);for(int i=0;i<2;i++)b.add("egg",CookingBatch.Cut.WHOLE,1,false,false);b.add("scallion",CookingBatch.Cut.DICE,1,false,false);b.stir();b.stir();turnAfterSetting(b);assertTrue(r.matches(b));b.coldMixes=0;assertEquals("cold_mix",r.problem(b).orElseThrow().key());}
    @Test void fishNeedsPepperAndARealTurn(){var r=recipe("pan_fried_fish");var b=batch(CookingBatch.Method.FRY);b.temperature=130;for(int i=0;i<2;i++)b.add("fish",CookingBatch.Cut.WHOLE,1.6,false,false);b.season("pepper_powder");turnAfterSetting(b);assertTrue(r.matches(b));b.seasoningCounts.remove("pepper_powder");b.season("chili_powder");assertEquals("seasoning",r.problem(b).orElseThrow().key());}
    @Test void turningImmediatelyBeforeServingStillNeedsTheOtherSideHeated(){var r=recipe("pan_fried_fish");var b=batch(CookingBatch.Method.FRY);b.temperature=130;for(int i=0;i<2;i++)b.add("fish",CookingBatch.Cut.WHOLE,1.6,false,false);b.season("pepper_powder");ready(b);b.turn();assertEquals("turn",r.problem(b).orElseThrow().key());b.ingredients.forEach(p->p.cooked=1.31);assertTrue(r.matches(b));}
    @Test void actualSugarColourAndLowCoveredStewingProduceBraisedPork(){var b=batch(CookingBatch.Method.STEW);b.sugar=1;for(int i=0;i<100&&b.caramelSeconds<3;i++)b.tick(2,false);assertEquals(3,b.caramelSeconds);for(int i=0;i<3;i++)b.add("pork",CookingBatch.Cut.DICE,1.6,false,false);b.add("ginger",CookingBatch.Cut.SLICE,1,false,false);b.addWater(2);for(int i=0;i<160;i++)b.tick(1,true);assertTrue(b.ready());assertTrue(recipe("braised_pork").matches(b));}
    @Test void SugarWaterCannotPretendToBeCaramel(){var b=batch(CookingBatch.Method.STEW);b.sugar=1;b.addWater(2);for(int i=0;i<60;i++)b.tick(2,false);for(int i=0;i<3;i++)b.add("pork",CookingBatch.Cut.DICE,1.6,false,false);b.add("ginger",CookingBatch.Cut.SLICE,1,false,false);ready(b);assertEquals("caramel",recipe("braised_pork").problem(b).orElseThrow().key());}
    @Test void BurntSugarCannotRecoverByCooling(){var b=batch(CookingBatch.Method.STEW);b.sugar=1;for(int i=0;i<80;i++)b.tick(2,false);assertTrue(b.burntSugarSeconds>=5);b.temperature=160;b.add("pork",CookingBatch.Cut.DICE,1.6,false,false);assertFalse(b.ingredients.getFirst().caramelOnAdd);}
    @Test void eggplantSauceAndSugarGoAfterSoftening(){var r=recipe("braised_eggplant");var b=batch(CookingBatch.Method.STIR_FRY);b.temperature=130;b.add("garlic",CookingBatch.Cut.MINCE,1,false,false);for(int i=0;i<3;i++)b.add("eggplant",CookingBatch.Cut.DICE,1,false,false);b.sugar=1;b.ingredients.forEach(p->p.cooked=.8);b.season("soy");b.season("sugar");ready(b);stir(b);assertTrue(r.matches(b));b.seasoningProgress.put("sugar",.2);assertEquals("finish",r.problem(b).orElseThrow().key());}
    @Test void saladNeedsSesameOilAndCannotBeHeatedThenCooled(){var r=recipe("cucumber_salad");var b=batch(CookingBatch.Method.MIX);b.vinegar=1;for(int i=0;i<2;i++)b.add("cucumber",CookingBatch.Cut.DICE,1,false,true);b.add("garlic",CookingBatch.Cut.MINCE,1,false,true);b.season("sesame_oil");stir(b);assertTrue(r.matches(b));b.maximumFoodTemperature=80;assertEquals("cold",r.problem(b).orElseThrow().key());b.maximumFoodTemperature=20;b.seasoningCounts.remove("sesame_oil");b.season("rapeseed_oil");assertEquals("seasoning",r.problem(b).orElseThrow().key());}
    @Test void pickleBatchOnlyFermentsWhileSealedInColdBrine(){var b=batch(CookingBatch.Method.FERMENT);b.oil=0;b.salt=2;b.addWater(6);for(int i=0;i<3;i++)b.add("cabbage",CookingBatch.Cut.SHRED,1,false,false);b.add("chili",CookingBatch.Cut.SLICE,1,false,false);b.add("garlic",CookingBatch.Cut.MINCE,1,false,false);for(int i=0;i<1200;i++)b.tick(0,false);assertFalse(b.ready());assertEquals(0,b.fermentationSeconds);for(int i=0;i<1200;i++)b.tick(0,true);assertTrue(b.ready());assertTrue(recipe("pickled_cabbage").matches(b));b.fermentationSeconds=0;assertEquals("ferment",recipe("pickled_cabbage").problem(b).orElseThrow().key());}
    @Test void skewersNeedCuminDryRoastingAndTurning(){var r=recipe("meat_skewers");var b=batch(CookingBatch.Method.BAKE);for(int i=0;i<3;i++)b.add("skewers",CookingBatch.Cut.WHOLE,1.6,false,false);b.season("cumin_powder");b.roastSeconds=15;turnAfterSetting(b);assertTrue(r.matches(b));b.seasoningCounts.remove("cumin_powder");b.season("pepper_powder");assertEquals("seasoning",r.problem(b).orElseThrow().key());}
    @Test void duckNeedsColdMarinationAndASecondHoneyBrushing(){var r=recipe("honey_roast_duck");var b=batch(CookingBatch.Method.BAKE);for(int i=0;i<3;i++)b.add("duck",CookingBatch.Cut.WHOLE,1.6,false,false);b.season("honey");b.season("soy");for(int i=0;i<10;i++)b.tick(0,false);ready(b);b.ovenSeconds=15;b.roastSeconds=15;assertEquals("finish",r.problem(b).orElseThrow().key());b.ingredients.forEach(p->p.cooked=.6);b.season("honey");ready(b);assertTrue(r.matches(b));b.ingredients.getFirst().marinatedSeconds=0;assertEquals("marinate",r.problem(b).orElseThrow().key());}
    @Test void roastPotatoNeedsCutPiecesAnOvenAndSoftening(){var r=recipe("roast_potatoes");var b=batch(CookingBatch.Method.BAKE);for(int i=0;i<3;i++)b.add("potato",CookingBatch.Cut.DICE,1,false,false);b.ovenSeconds=15;b.roastSeconds=15;ready(b);assertEquals("soften",r.problem(b).orElseThrow().key());b.ingredients.forEach(p->p.cooked=1.2);assertTrue(r.matches(b));b.ingredients.getFirst().cut=CookingBatch.Cut.WHOLE;assertEquals("cut",r.problem(b).orElseThrow().key());}
    @Test void softeningProgressHasItsOwnTargetInsteadOfStoppingAtOrdinaryCookedness(){var b=new CookingBatch();b.add("rice",CookingBatch.Cut.WHOLE,1,true,false);b.ingredients.getFirst().cooked=1;assertTrue(b.ready());assertEquals(71,b.progress(1.4));b.ingredients.getFirst().cooked=1.4;assertEquals(100,b.progress(1.4));}
}
